INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('cheapest-route', 8, NULL, 'def gen():
    _s = [1029427878]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    W = 1000000000
    CHAIN = 0
    N = 100000
    M = 180000
    lines = []
    for _ in range(M):
        u = r(1, N)
        v = r(1, N)
        lines.append(f"{u} {v} {r(1, W)}")
    if CHAIN:
        for i in range(1, N):
            lines.append(f"{i} {i + 1} {r(W // 2, W)}")
    return f"{N} {len(lines)}\n" + "\n".join(lines) + "\n"
', '4238740486', 0);
INSERT INTO challenge_tests (test_set, idx, input, gen, expected, sample) VALUES ('cheapest-route', 9, NULL, 'def gen():
    _s = [1281409588]
    def _n():
        _s[0] = (_s[0] * 1103515245 + 12345) % 2147483648
        return _s[0] >> 8
    def r(lo, hi):
        return lo + ((_n() << 23) | _n()) % (hi - lo + 1)
    W = 1000
    CHAIN = 1
    N = 100000
    M = 100000
    lines = []
    for _ in range(M):
        u = r(1, N)
        v = r(1, N)
        lines.append(f"{u} {v} {r(1, W)}")
    if CHAIN:
        for i in range(1, N):
            lines.append(f"{i} {i + 1} {r(W // 2, W)}")
    return f"{N} {len(lines)}\n" + "\n".join(lines) + "\n"
